<script setup lang="ts">import type{CascaderOption}from'@fex-design/core/cascader/types';import{onUnmounted,ref}from'vue';import{remoteRegionSearch}from'./data';import DemoCascader from'./demo-cascader.vue';import Demo from'./demo-section.vue';const options=ref<readonly CascaderOption[]>([]),loading=ref(false);let timer:ReturnType<typeof setTimeout>|undefined,request=0;function search(keyword:string){if(timer)clearTimeout(timer);const id=++request;if(!keyword.trim()){loading.value=false;return}loading.value=true;timer=setTimeout(()=>{if(id!==request)return;options.value=remoteRegionSearch(keyword);loading.value=false},800)}onUnmounted(()=>{request++;if(timer)clearTimeout(timer)})</script><template><Demo title="Remote search" description="Server-style search returns ancestor-preserving trees and ignores stale responses."><DemoCascader show-search :filter-option="false" :loading="loading" :options="options" @search="search"/></Demo></template>
